//! Catálogo de estrellas brillantes para la acción Astronomía.
//!
//! Generado del Yale Bright Star Catalog (5.ª ed.): las 2 849 más brillantes
//! con designación de Bayer o de Flamsteed (de cada sistema doble o
//! múltiple, solo la más brillante). Coordenadas J2000 en grados decimales.

// Son datos: magnitudes como 3.14 no son π
#![allow(clippy::approx_constant)]

/// Una estrella del catálogo
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Star {
    /// Nombre propio («Sirius») o, si no tiene, su designación
    pub name: &'static str,
    /// Ascensión recta en grados [0, 360)
    pub ra: f64,
    /// Declinación en grados [-90, 90]
    pub dec: f64,
    /// Magnitud visual (V)
    pub mag: f64,
    /// Designación de Bayer («α CMa») o, si no tiene, de Flamsteed («61 Cyg»)
    pub bayer: &'static str,
    /// Constelación («Canis Major»)
    pub con: &'static str,
}

