// Fuente: Yale Bright Star Catalog, 5.ª ed. (Hoffleit y Warren, 1991; Harvard
// SAO, dominio público), versión JSON de github.com/brettonw/YaleBrightStarCatalog.
// Nombres propios: los de la sección «Star names» de sus notas.

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalogo() {
        assert_eq!(STARS.len(), 2849);
        assert_eq!(STARS[0].name, "Sirius");
        assert!(STARS.windows(2).all(|w| w[0].mag <= w[1].mag));
        assert!(STARS.iter().all(|s| (0.0..360.0).contains(&s.ra) && (-90.0..=90.0).contains(&s.dec)));
        let vega = STARS.iter().find(|s| s.name == "Vega").unwrap();
        assert!((vega.ra - 279.23).abs() < 0.05 && (vega.dec - 38.78).abs() < 0.05);
    }
}
